-- HR & Employees dataset (generated by scripts/build_datasets.py; do not edit by hand)
DROP TABLE IF EXISTS performance_reviews CASCADE;
DROP TABLE IF EXISTS salary_history CASCADE;
DROP TABLE IF EXISTS employees CASCADE;
DROP TABLE IF EXISTS jobs CASCADE;
DROP TABLE IF EXISTS departments CASCADE;
DROP TABLE IF EXISTS locations CASCADE;

CREATE TABLE locations (
  location_id INTEGER PRIMARY KEY,
  city VARCHAR(60) NOT NULL,
  country VARCHAR(60) NOT NULL,
  postal_code VARCHAR(12)
);

CREATE TABLE departments (
  department_id INTEGER PRIMARY KEY,
  department_name VARCHAR(60) NOT NULL UNIQUE,
  location_id INTEGER REFERENCES locations(location_id),
  budget NUMERIC(12,2) CHECK (budget >= 0)
);

CREATE TABLE jobs (
  job_id INTEGER PRIMARY KEY,
  job_title VARCHAR(80) NOT NULL,
  min_salary NUMERIC(10,2) NOT NULL,
  max_salary NUMERIC(10,2) NOT NULL,
  CHECK (max_salary >= min_salary)
);

CREATE TABLE employees (
  employee_id INTEGER PRIMARY KEY,
  first_name VARCHAR(40) NOT NULL,
  last_name VARCHAR(40) NOT NULL,
  email VARCHAR(120) UNIQUE,
  phone VARCHAR(20),
  hire_date DATE NOT NULL,
  job_id INTEGER NOT NULL REFERENCES jobs(job_id),
  salary NUMERIC(10,2) NOT NULL CHECK (salary > 0),
  commission_pct NUMERIC(4,2) CHECK (commission_pct BETWEEN 0 AND 0.5),
  manager_id INTEGER REFERENCES employees(employee_id),
  department_id INTEGER REFERENCES departments(department_id),
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  termination_date DATE,
  CHECK (termination_date IS NULL OR termination_date >= hire_date)
);

CREATE TABLE salary_history (
  salary_history_id INTEGER PRIMARY KEY,
  employee_id INTEGER NOT NULL REFERENCES employees(employee_id),
  effective_date DATE NOT NULL,
  old_salary NUMERIC(10,2),
  new_salary NUMERIC(10,2) NOT NULL CHECK (new_salary > 0),
  reason VARCHAR(30) NOT NULL CHECK (reason IN ('hire','merit','promotion','market_adjustment','demotion'))
);

CREATE TABLE performance_reviews (
  review_id INTEGER PRIMARY KEY,
  employee_id INTEGER NOT NULL REFERENCES employees(employee_id),
  reviewer_id INTEGER REFERENCES employees(employee_id),
  review_date DATE NOT NULL,
  rating SMALLINT CHECK (rating BETWEEN 1 AND 5),
  comments TEXT
);









